#include <bits/stdc++.h>
using namespace std;
struct Con{int c;array<int,9>a;uint16_t support;};
array<uint16_t,9> graph_from_code(uint64_t code){array<uint16_t,9>a{};int b=0;for(int i=0;i<9;i++)for(int j=i+1;j<9;j++,b++)if((code>>b)&1ULL){a[i]|=1u<<j;a[j]|=1u<<i;}return a;}
string g6(const array<uint16_t,9>&a){string s;s.push_back(char(72));int val=0,cnt=0;for(int j=1;j<9;j++)for(int i=0;i<j;i++){val=(val<<1)|((a[i]>>j)&1);cnt++;if(cnt==6){s.push_back(char(val+63));val=0;cnt=0;}}if(cnt){val<<=(6-cnt);s.push_back(char(val+63));}return s;}
bool find_scheme(const array<uint16_t,9>&adj,array<int,9>&sol,int&max_used){int deg[9],Delta=0;for(int i=0;i<9;i++){deg[i]=__builtin_popcount((unsigned)adj[i]);Delta=max(Delta,deg[i]);}vector<Con>cs;for(int u=0;u<9;u++)for(int v=u+1;v<9;v++)if(adj[u]&(1u<<v)){Con q;q.c=deg[u]-deg[v];q.a.fill(0);q.support=0;q.a[u]+=deg[u];q.a[v]-=deg[v];for(int w=0;w<9;w++)if(adj[u]&(1u<<w))q.a[w]++;for(int w=0;w<9;w++)if(adj[v]&(1u<<w))q.a[w]--;for(int i=0;i<9;i++)if(q.a[i])q.support|=1u<<i;cs.push_back(q);}int score[9]={};for(auto&q:cs)for(int i=0;i<9;i++)if(q.a[i])score[i]++;array<int,9>order;iota(order.begin(),order.end(),0);sort(order.begin(),order.end(),[&](int x,int y){if(score[x]!=score[y])return score[x]>score[y];if(deg[x]!=deg[y])return deg[x]>deg[y];return x<y;});vector<vector<int>>vcs(9);for(int j=0;j<(int)cs.size();j++)for(int i=0;i<9;i++)if(cs[j].a[i])vcs[i].push_back(j);vector<int>partial(cs.size()),rem(cs.size());for(int j=0;j<(int)cs.size();j++){partial[j]=cs[j].c;rem[j]=__builtin_popcount((unsigned)cs[j].support);}array<int,9>asg;asg.fill(-1);function<bool(int)>dfs=[&](int k){if(k==9){sol=asg;int m=0;for(int x:sol)m=max(m,x);max_used=max(max_used,m);return true;}int i=order[k];for(int val=0;val<=Delta;val++){bool bad=false;for(int j:vcs[i]){partial[j]+=cs[j].a[i]*val;rem[j]--;if(rem[j]==0&&partial[j]==0)bad=true;}if(!bad){asg[i]=val;if(dfs(k+1))return true;asg[i]=-1;}for(int j:vcs[i]){partial[j]-=cs[j].a[i]*val;rem[j]++;}}return false;};return dfs(0);}
bool verify(const array<uint16_t,9>&a,const array<int,9>&rho){int d[9],D=0,s[9];for(int i=0;i<9;i++){d[i]=__builtin_popcount((unsigned)a[i]);D=max(D,d[i]);}for(int i=0;i<9;i++)if(rho[i]<0||rho[i]>D)return false;for(int i=0;i<9;i++){s[i]=(1+rho[i])*d[i];for(int j=0;j<9;j++)if(a[i]&(1u<<j))s[i]+=rho[j];}for(int i=0;i<9;i++)for(int j=i+1;j<9;j++)if(a[i]&(1u<<j))if(s[i]==s[j])return false;return true;}
int main(int argc,char**argv){if(argc!=2){cerr<<"usage: bmo_n9_witness_exact N9_CODES\n";return 2;}ifstream in(argv[1]);uint64_t code;long long n=0;int maxused=0;map<int,long long>byD;while(in>>code){auto a=graph_from_code(code);int D=0;for(int i=0;i<9;i++)D=max(D,__builtin_popcount((unsigned)a[i]));byD[D]++;array<int,9>sol;if(!find_scheme(a,sol,maxused)||!verify(a,sol)){cout<<"FAIL code="<<code<<" g6="<<g6(a)<<" Delta="<<D<<"\n";return 1;}n++;}cout<<"n9_connected_isomorphism_classes="<<n<<"\n";cout<<"n9_counts_by_Delta={";bool first=true;for(auto[d,c]:byD){if(!first)cout<<", ";first=false;cout<<d<<":"<<c;}cout<<"}\n";cout<<"failures_order9=0\n";cout<<"max_witness_value_seen_order9="<<maxused<<"\n";cout<<"VERDICT=PASS_ALL_CONNECTED_SIMPLE_GRAPHS_ORDER_9\nMETRIC=n_all=9\nSTATUS=SELF_CHECK_ONLY_PARTIAL_FOR_CONJECTURE_2_6\n";}
